import{_ as t,C as l,o as i,c as r,j as s,a as e,E as p,ag as o}from"./chunks/framework.DUTPmUpA.js";const f=JSON.parse('{"title":"Предварительное кэширование, исправление и предотвращение проблем","description":"","frontmatter":{"title":"Предварительное кэширование, исправление и предотвращение проблем","author":"Noya","steamId":"76561198046984233","date":"07.02.2015"},"headers":[],"relativePath":"scripting/precache-fixing-and-avoiding-issues.md","filePath":"scripting/precache-fixing-and-avoiding-issues.md"}'),u={name:"scripting/precache-fixing-and-avoiding-issues.md"};function c(d,n,b,m,g,q){const a=l("Gfycat");return i(),r("div",null,[n[0]||(n[0]=s("p",null,"е, исправление и предотвращение проблем",-1)),n[1]||(n[1]=s("p",null,[e("При создании юнитов через KV и Lua вам, возможно, придется столкнуться с дилеммой прекеша. Это также относится к частицам и звукам. Я кратко говорил об этом в "),s("a",{href:"/abilities/ability-keyvalues"},"precache section of the datadriven breakdown"),e(", но здесь у меня есть простой пример, который поможет понять суть вопроса.")],-1)),n[2]||(n[2]=s("p",null,"Итак, если вы видите невыбираемую оранжевую ОШИБКУ в качестве модели юнита, значит, у вас проблема с моделью предварительного кэширования:",-1)),n[3]||(n[3]=s("p",null,"Недостающие частицы обозначены красными крестиками:",-1)),p(a,{id:"SinfulShamefulBittern"}),n[4]||(n[4]=o(`<p><strong>Как это исправить и избежать?</strong> Во-первых, управляемое данными действие <code>&quot;SpawnUnit&quot;</code> всегда будет предварительно кэшировать пользовательский модуль UnitName и любые косметические элементы, которые вы к нему прикрепили. Например, в этом <a href="https://github.com/MNoya/DotaCraft/blob/master/scripts/npc/abilities/warden_avatar_of_vengeance.txt" target="_blank" rel="noreferrer">Avatar of Vengeance ability</a> я создам Призрака с некоторыми шляпами:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&quot;SpawnUnit&quot;</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    &quot;UnitName&quot;	&quot;npc_avatar_of_vengeance&quot;</span></span>
<span class="line"><span>    &quot;UnitCount&quot;	&quot;1&quot;</span></span>
<span class="line"><span>    &quot;SpawnRadius&quot;	&quot;100&quot;</span></span>
<span class="line"><span>    &quot;Duration&quot;	&quot;%duration&quot;</span></span>
<span class="line"><span>    &quot;Target&quot;		&quot;CASTER&quot;</span></span>
<span class="line"><span>    &quot;OnSpawn&quot;</span></span>
<span class="line"><span>    {</span></span>
<span class="line"><span>	&quot;FireSound&quot;</span></span>
<span class="line"><span>	{</span></span>
<span class="line"><span>	    &quot;EffectName&quot; &quot;Hero_Spectre.Haunt&quot;</span></span>
<span class="line"><span>	    &quot;Target&quot;	 &quot;CASTER&quot;</span></span>
<span class="line"><span>	}</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br></div></div><p>Теперь будет много-много раз, что SpawnUnit не сработает, и вам придется создавать юниты в lua, используя функцию <code>CreateUnitByName</code>.</p><p>Если бы я пошел дальше и просто создал свой модуль в Lua (упрощенный пример <a href="https://github.com/MNoya/DotaCraft/blob/master/scripts/vscripts/heroes/warden/avatar_of_vengeance.lua#L35" target="_blank" rel="noreferrer">this script</a>):</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>lua</span></span>
<span class="line"><span>function SpiritOfVengeanceSpawn( event )</span></span>
<span class="line"><span>    local caster = event.caster</span></span>
<span class="line"><span>    local unit_name = &quot;npc_spirit_of_vengeance&quot;</span></span>
<span class="line"><span>    local origin = caster:GetAbsOrigin()</span></span>
<span class="line"><span>    local spirit = CreateUnitByName(unit_name, origin, true, caster, caster, caster:GetTeamNumber())</span></span>
<span class="line"><span>end</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><p>Без какого-либо предыдущего предварительного кэширования я получу что-то вроде модели ERROR, как раньше, или, если я запускаю инструменты не в первый раз (потому что после первого запуска он пытается сохранить некоторые модели для хранения в кеше), что-то вроде этого:</p><p>Да, это плохо, вот как это исправить:</p><p><strong>Всегда добавляйте управляемый данными блок предварительного кэширования со всеми моделями, звуками и частицами, которые могут использовать ваши способности</strong></p><p>В этом случае я предварительно кэширую все модели и окружающие частицы, которые использую, внутри основной способности, управляемой данными.</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&quot;precache&quot;</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>	&quot;soundfile&quot;	&quot;soundevents/game_sounds_heroes/game_sounds_spectre.vsndevts&quot;</span></span>
<span class="line"><span>	&quot;model&quot;		&quot;models/heroes/vengeful/vengeful.vmdl&quot;</span></span>
<span class="line"><span>	&quot;model&quot;		&quot;models/items/vengeful/vengeful_immortal_weapon/vengeful_immortal_weapon.vmdl&quot;</span></span>
<span class="line"><span>	&quot;model&quot;		&quot;models/items/vengefulspirit/fallenprincess_shoulders/fallenprincess_shoulders.vmdl&quot;</span></span>
<span class="line"><span>	&quot;model&quot;		&quot;models/items/vengefulspirit/fallenprincess_legs/fallenprincess_legs.vmdl&quot;</span></span>
<span class="line"><span>	&quot;model&quot;		&quot;models/items/vengefulspirit/fallenprincess_head/fallenprincess_head.vmdl&quot;</span></span>
<span class="line"><span>	&quot;particle&quot;      &quot;particles/units/heroes/hero_vengeful/vengeful_ambient.vpcf&quot;</span></span>
<span class="line"><span>	&quot;particle&quot;      &quot;particles/econ/items/vengeful/vengeful_wing_fallenprincess/venge_wingsoffallenprincess_ambient.vpcf&quot;</span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br></div></div><p>Теперь все модели будут загружаться правильно.</p><p>И последнее замечание: некоторые косметические средства, которые вы, возможно, захотите использовать, содержат свои собственные частицы, и их названия сложно узнать. В первой гифке (тот, что с красными крестами) мне не хватало эффекта частиц крыльев для Fallprincess_shoulders. В этом случае вы также можете найти частицы, используемые косметическим средством, в его определении <a href="https://raw.githubusercontent.com/dotabuff/d2vpk/master/dota_pak01/scripts/items/items_game.txt" target="_blank" rel="noreferrer"><code>item_game.txt</code></a>:</p><br><p>Теперь после добавления этой частицы (которую я только что нашел в браузере ресурсов и скопировал путь к <code>.vpcf</code>) все отображается правильно:</p>`,14)),p(a,{id:"SphericalHonorableChevrotain"})])}const _=t(u,[["render",c]]);export{f as __pageData,_ as default};
